CREATE TABLE IF NOT EXISTS biz_performance_batch (id varchar(36) PRIMARY KEY, filename varchar(255) NOT NULL, uploaded_by varchar(36) NOT NULL, total_rows int NOT NULL DEFAULT 0, status varchar(20) NOT NULL DEFAULT 'active', uploaded_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS biz_performance_record (id varchar(36) PRIMARY KEY, batch_id varchar(36) NOT NULL, assessment_year int NOT NULL, supplier varchar(200) NOT NULL, organization varchar(200) NOT NULL, score_1 decimal(8,3) NULL, score_2 decimal(8,3) NULL, score_3 decimal(8,3) NULL, score_4 decimal(8,3) NULL, score_5 decimal(8,3) NULL, score_6 decimal(8,3) NULL, score_7 decimal(8,3) NULL, score_8 decimal(8,3) NULL, score_9 decimal(8,3) NULL, score_10 decimal(8,3) NULL, score_11 decimal(8,3) NULL, score_12 decimal(8,3) NULL, created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uk_perf_batch_supplier_org(batch_id,supplier,organization), KEY idx_perf_org(organization));
ALTER TABLE biz_performance_record ADD COLUMN city varchar(160) NULL;
ALTER TABLE biz_performance_record ADD COLUMN region varchar(160) NULL;
